design.css:
/* Coral — the Zangetsu look (docs/theme-references/zangetsu.md): near-black, one coral accent, Nunito. */

/* Featured hero: a rounded art card inset from the edges, glowing in the artwork's own colour. */
[data-slot="home.hero"] {
  margin: 8px 16px 28px !important;
  width: auto !important;
  border-radius: 28px;
  overflow: hidden;
  box-shadow: 0 18px 70px -10px rgb(var(--hero-ambient-rgb, 255 77 87) / 0.55);
}
/* Desktop: clear the window's title strip above the card. */
@media (min-width: 641px) { [data-slot="home.hero"] { margin-top: 44px !important; } }
[data-part="coral.hero"]::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(11, 11, 15, 0.95), rgba(11, 11, 15, 0.35) 45%, rgba(11, 11, 15, 0) 65%) !important;
  pointer-events: none;
}
[data-part="coral.hero"]::after { z-index: 1; }
[data-part="coral.hero"] > :not(:first-child) { z-index: 2; }
[data-part="coral.info"] { padding-bottom: 36px; }
[data-part="coral.meta"] { width: 100%; overflow: visible !important; text-transform: uppercase; letter-spacing: 0.8px; }
[data-part="coral.play"] { width: 138px; justify-content: center; gap: 8px; }
[data-part="coral.glass"] { width: 44px; justify-content: center; padding: 0; background: rgba(255, 255, 255, 0.14) !important; backdrop-filter: blur(10px); line-height: 1; }
/* Slide markers are drawn on the marker's track; the button around it keeps its hit area unpainted. */
[data-part="hero.dot.track"] { width: 6px !important; height: 6px !important; border-radius: 3px !important; background: rgba(255, 255, 255, 0.35) !important; }
[data-part="hero.dot"][data-active] [data-part="hero.dot.track"] { width: 20px !important; background: #fff !important; }

/* Rows: 20 px headings with a wide gap above, a "See All" link in the accent. */
[data-part="row.title"], [data-part="block.title"] { font-size: 20px; font-weight: 700; letter-spacing: -0.3px; color: #fff; }
[data-part="row.more"] { color: #ff4d57; font-weight: 600; }

/* Poster cards: bottom scrim, the ★ score pill top right, a fixed two-line title. */
[data-part="coral.poster"]::after {
  content: "";
  position: absolute;
  inset: 55% 0 0;
  border-radius: 0 0 12px 12px;
  background: linear-gradient(to top, rgba(11, 11, 15, 0.7), rgba(11, 11, 15, 0));
  pointer-events: none;
}
[data-part="coral.score"] { margin: 6px; background: rgba(0, 0, 0, 0.6); z-index: 1; }
[data-part="coral.card-title"] { line-height: 1.3; min-height: 2.6em; }

/* ── Series page (phone): Zangetsu's detail screen. Spec: docs/theme-references/zangetsu-series.md ──
   Built on the API 3 episode-toolbar/state/section keys (design.json `mobile.detail`): order:"none",
   toolbar:"header", paging:"ranges", nav:"hidden", sections, and the `z.ep-*` episode template. Only
   pieces with no matching hook still use a structural/aria-label selector (marked INTERIM below). */

/* Content column: 16 px gutter, Zangetsu's order (title, Play, second button, synopsis, credit lines,
   icon row, countdown, airing, tabs). No `detail.content` hook exists yet, so the column that holds
   `detail.actions` is still found structurally. */
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) { display: flex; flex-direction: column; padding-inline: 16px; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > * { order: 20; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > div:has(> [data-part="detail.poster"]) { order: 1; margin-top: 14px; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > [data-part="button"][data-variant="primary"] { order: 2; margin-top: 18px; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > [data-part="detail.list-button"] { order: 3; margin-top: 10px; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > [data-part="detail.synopsis"] { order: 4; margin-top: 18px; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > [data-part="detail.genres"] { order: 5; margin-top: 14px; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > [data-part="detail.byline"] { order: 6; margin-top: 2px; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > [data-part="detail.actions"] { order: 7; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > [data-part="detail.countdown"] { order: 25; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > div:has(> [data-part="detail.airing"]) { order: 26; margin-top: 6px; }
[data-slot="detail"][data-variant="phone"] > div:has(> [data-part="detail.actions"]) > div:has(> [data-part="tabs"]) { order: 30; margin-top: 0; }

/* No poster, no alt title, no built-in facts line: the `detail.header` template is the meta line. */
[data-slot="detail"][data-variant="phone"] :is([data-part="detail.poster"], [data-part="detail.alt-title"], [data-part="detail.meta"]) { display: none; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.title"] { font-size: 28px; font-weight: 700; letter-spacing: -0.5px; line-height: 1.1; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.header"] { margin-top: 8px; }
[data-part="coral.detail-meta"] { line-height: 1.35; }

/* Artwork: 320 px + status bar, full-bleed, sharp cover fallback, Zangetsu's two scrims. */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] { height: calc(320px + env(safe-area-inset-top)); min-height: 0; max-height: none; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] > img { opacity: 1; filter: none; transform: none; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"] > div { display: none; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"]::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(to top, rgb(11 11 15 / 0.95), rgb(11 11 15 / 0) 65%), linear-gradient(to bottom, rgb(11 11 15 / 0.6), rgb(11 11 15 / 0) 50%);
}

/* Floating bar (real hook now): plain arrow, opaque and borderless once titled. */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.bar"] { border-bottom-width: 0; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.bar"][data-solid] { background-color: hsl(var(--background)); -webkit-backdrop-filter: none; backdrop-filter: none; border-bottom-width: 0; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.bar"] span { font-size: 17px; font-weight: 600; }

/* Play: white 52 px, radius 8, filled 26 px glyph. The list button below it: Zangetsu's grey Download
   (listButton:"full" is the stand-in for the real download button until the client grows one). */
[data-slot="detail"] [data-part="button"][data-variant="primary"] { border-radius: 8px; background-color: #fff; color: #000; }
[data-slot="detail"][data-variant="phone"] [data-part="button"][data-variant="primary"] { width: 100%; height: 52px; padding: 0; gap: 8px; font-size: 16px; font-weight: 600; letter-spacing: -0.2px; }
[data-slot="detail"][data-variant="phone"] [data-part="button"][data-variant="primary"] svg { width: 26px; height: 26px; fill: currentColor; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.list-button"][data-variant="full"] {
  height: 52px; padding: 0; border: 0; border-radius: 8px; background-color: #20212a; color: #fff;
  font-size: 16px; font-weight: 600; letter-spacing: -0.2px; text-transform: none;
}

/* Synopsis: izumi already clamps this to 3 lines on the phone stack (Tailwind `line-clamp-3` on
   the component itself); an accent "Read more" is appended inline right after the truncated text
   (izumi expands in place — no `readMore` tab-jump key exists yet). A `padding-bottom` +
   `position: absolute` label here fights the clamp's own box model and leaks a 4th line in
   Chromium, so the label rides the clamped flow instead of overlaying it. */
[data-slot="detail"][data-variant="phone"] button[data-part="detail.synopsis"] { position: relative; padding-right: 78px; font-size: 15px; line-height: 1.35; color: #a7a7b2; }
[data-slot="detail"][data-variant="phone"] button[data-part="detail.synopsis"]::after { content: "Read more"; position: absolute; right: 0; bottom: 0; font-size: 13px; font-weight: 700; color: #ff4d57; }

/* Credit lines, built from the real `detail.genres` chip rail and `detail.byline` line (no `credits`
   template/`starring` field exist yet, so this is the closest match: Zangetsu's Genres fallback and
   Creators line, grey and mixed-case — not the coral uppercase tags the old draft used). */
[data-slot="detail"][data-variant="phone"] [data-part="detail.genres"] {
  flex-wrap: wrap; gap: 0 4px; margin-inline: 0; padding: 0; overflow: hidden; max-height: 2.6em;
  font-size: 13px; line-height: 1.3; font-weight: 500; color: #a7a7b2;
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.genres"]::before { content: "Genres: "; color: #6e6e78; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.genres"] [data-part="chip"] { padding: 0; border: 0; border-radius: 0; background: none; color: inherit; font: inherit; letter-spacing: 0; text-transform: none; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.genres"] [data-part="chip"]:nth-child(n + 5) { display: none; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.genres"] [data-part="chip"]:not(:last-child):not(:nth-child(4))::after { content: ","; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.byline"] { gap: 0 4px; font-size: 13px; line-height: 1.3; font-weight: 500; color: #a7a7b2; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.byline"]::before { content: "Creators: "; color: #6e6e78; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.byline"] > :not(a) { display: none; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.byline"] > a { font-weight: 500; color: inherit; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.byline"]:not(:has(> a)) { display: none; }

/* Icon-over-label row: no fills, 24 px icons, 11/600 grey labels, spaced around. Trailer/Share/More
   are still bare buttons with no `data-action` hook, so their labels are generated off aria-label. */
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] { justify-content: space-around; gap: 0; margin: 20px -8px 8px; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button:not([aria-label="Close menu"]) {
  flex: 0 0 auto; display: flex; flex-direction: column; align-items: center; gap: 6px;
  height: auto; min-width: 56px; padding: 6px; border-radius: 12px; background-color: transparent;
  color: #a7a7b2; font-size: 11px; line-height: 1.3; font-weight: 600;
}
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button svg { width: 24px; height: 24px; color: #fff; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button[aria-label="Share series"]::after { content: "Share"; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button[aria-label="Trailer"]::after { content: "Trailer"; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > button[aria-label="More"]::after { content: "More"; }

/* Airing countdown as Zangetsu's line: grey text, accent bold countdown, no pill. */
[data-slot="detail"][data-variant="phone"] [data-part="detail.countdown"] { margin-top: 14px; padding: 0; border-radius: 0; background: none; font-size: 15px; line-height: 1.35; font-weight: 400; color: #a7a7b2; }
[data-slot="detail"][data-variant="phone"] [data-part="detail.countdown"] > span { font-weight: 700; color: #ff4d57; }

/* Tabs: pinned under the bar, left-anchored, 24 px between labels, 2.5 px accent line under the text.
   Episodes · Cast · Relations · Details, via design.json `sections` (no `tabsPinned` key yet, so the
   pin is still CSS `position: sticky`). */
[data-slot="detail"] [data-part="tab"] { font-size: 15px; font-weight: 500; color: #a7a7b2; }
[data-slot="detail"] [data-part="tab"][data-active] { font-weight: 600; color: #ff4d57; }
[data-slot="detail"] [data-part="tab"][data-active] > span { left: 12px; right: 12px; bottom: 0; height: 2.5px; background-color: #ff4d57; }
[data-slot="detail"] [data-part="tabs"][data-variant="underline"] { border-bottom: 0; }
[data-slot="detail"][data-variant="phone"] [data-part="tabs"] {
  position: sticky; top: calc(max(0.5rem, env(safe-area-inset-top)) + 3rem); z-index: 20;
  gap: 0; margin: 0 -16px; padding: 0 0 0 16px; background-color: hsl(var(--background));
}
[data-slot="detail"][data-variant="phone"] [data-part="tab"] { padding: 14px 24px 14px 0; border-radius: 0; background: none; transform: none; line-height: 1.2; }
[data-slot="detail"][data-variant="phone"] [data-part="tab"][data-active] > span { left: 2px; right: 26px; bottom: 8px; border-radius: 0; }

/* Episode toolbar (real hooks: `episodes.toolbar` header variant, `episodes.heading`/`.count`,
   `episodes.search`/`.layout`, `episodes.more`): "Episodes  N" left, quiet grey 36 px circles right,
   no sort (order:"none" already removes the control). The default bg-secondary/size-9 classes already
   land close to Zangetsu's #20212A/36 dp circles; this only tightens the exact numbers and typography. */
[data-slot="episodes.toolbar"][data-variant="header"] { margin-top: 8px; margin-bottom: 14px; gap: 8px; }
[data-part="episodes.heading"] { font-size: 17px; font-weight: 600; color: #fff; gap: 6px; }
[data-part="episodes.count"] { font-size: 13px; font-weight: 600; color: #a7a7b2; }
[data-slot="episodes.toolbar"][data-variant="header"] [data-part="episodes.search"],
[data-slot="episodes.toolbar"][data-variant="header"] [data-part="episodes.layout"],
[data-part="episodes.more"] { width: 36px; height: 36px; background-color: #20212a; color: #fff; }
[data-part="episodes.search"][data-active] { background-color: #ff4d57; color: #fff; }
[data-slot="episodes.toolbar"][data-variant="header"] svg { width: 20px; height: 20px; }
[data-part="episodes.menu"] { background-color: #16161c; border-color: rgb(255 255 255 / 0.08); }

/* Range chips (real hooks: `episodes.ranges` + `chip[data-active]`), 50 episodes per chip. Accent
   fill on the active chip: the default bg-primary is now white app-wide (see tokens.primary below),
   so the active state needs its own accent override to keep Zangetsu's selected-chip colour. */
[data-part="episodes.ranges"] { gap: 8px; padding-bottom: 4px; }
[data-part="episodes.ranges"] [data-part="chip"] { height: 34px; padding: 0 14px; border-radius: 9px; font-size: 13px; font-weight: 700; }
[data-part="episodes.ranges"] [data-part="chip"][data-active] { background-color: #ff4d57; color: #fff; }

/* Episode rows (the `z.ep-*` template, design.json `mobile.detail.episodes.card`): no card fill,
   10 px above/below, 16 px gutter, 14 px between the thumbnail and the text column. */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"] div:has(> div > [data-part="episode"][data-variant="template"]) { gap: 0; padding-inline: 0; }
[data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"] div:has(> [data-part="episode"][data-variant="template"]) { animation: none; }
[data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="template"] { padding: 10px 0; border-radius: 0; background-color: transparent; }
[data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="template"][aria-disabled="true"] { opacity: 1; }
[data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-title"] { line-height: 1.35; color: #fff; }
[data-slot="detail"] [data-slot="detail.episodes"] [aria-disabled="true"] [data-part="z.ep-title"] { color: #6e6e78; }
[data-slot="detail"] [data-slot="detail.episodes"] [aria-disabled="true"] [data-part="z.ep-play"] { color: rgb(255 255 255 / 0.7); }
[data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-meta"] { line-height: 1.3; }
[data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-synopsis"] { font-style: italic; line-height: 1.4; }
[data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-play"] { place-self: center; display: grid; place-items: center; width: 36px; height: 36px; padding-left: 2px; line-height: 1; }
[data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-rating"] { margin: 4px; padding: 2px 5px; line-height: 1.1; }
[data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-progress"] { background-color: rgb(0 0 0 / 0.5); }

/* Episode states (real hooks: `data-state`, `data-next`, `data-filler` on every `[data-part="episode"]`):
   a resume tile/row in accent, watched dimmed with a check, a CONTINUE badge, a FILLER badge. */
[data-part="episode"][data-state="watched"] [data-part="z.ep-thumb"]::after { content: ""; position: absolute; inset: 0; z-index: 1; background-color: rgb(0 0 0 / 0.45); }
[data-part="episode"][data-state="watched"] [data-part="z.ep-thumb"]::before { content: "✓"; position: absolute; top: 4px; right: 4px; z-index: 3; width: 16px; height: 16px; border-radius: 50%; background-color: #fff; color: #0b0b0f; font-size: 10px; font-weight: 900; line-height: 16px; text-align: center; }
[data-part="episode"][data-state="watched"] [data-part="z.ep-title"] { color: #a7a7b2 !important; }
[data-part="episode"][data-next] [data-part="z.ep-title"] { color: #ff4d57 !important; font-weight: 800 !important; }
[data-part="episode"][data-next] [data-part="z.ep-text"]::after { content: "CONTINUE"; align-self: flex-start; margin-top: 2px; padding: 2px 6px; border-radius: 6px; background-color: rgb(255 77 87 / 0.15); color: #ff4d57; font-size: 12px; font-weight: 700; letter-spacing: 0.8px; }
[data-part="episode"][data-filler] [data-part="z.ep-meta"]::after { content: "FILLER"; padding: 2px 6px; border-radius: 6px; background-color: rgb(255 77 87 / 0.15); color: #ff4d57; font-size: 12px; font-weight: 700; letter-spacing: 0.8px; }

/* Number grid: 5 columns, 10 px gaps, radius 10, 1.15 aspect. State colours come straight off
   `data-state`/`data-next`/`data-filler` now, instead of the old scoped `--primary` override. */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"] div:has(> [data-part="episode"][data-variant="number"]) { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; }
[data-part="episode"][data-variant="number"] { height: auto; aspect-ratio: 1.15; border: 0.5px solid rgb(255 255 255 / 0.08); border-radius: 10px; font-size: 15px; font-weight: 700; }
[data-part="episode"][data-variant="number"][data-state="watched"] { position: relative; background-color: hsl(var(--secondary)); color: #6e6e78; }
[data-part="episode"][data-variant="number"][data-state="watched"]::after { content: "✓"; position: absolute; top: 4px; right: 4px; font-size: 11px; color: #6e6e78; }
[data-part="episode"][data-variant="number"][data-next] { background-color: #ff4d57; color: #fff; box-shadow: none; border-color: transparent; }
[data-part="episode"][data-variant="number"][data-filler] { position: relative; }
[data-part="episode"][data-variant="number"][data-filler]::before { content: ""; position: absolute; top: 6px; left: 6px; width: 6px; height: 6px; border-radius: 50%; background-color: #6e6e78; }

/* Relations: 3 columns like Zangetsu (`detail.relations`). SmallCard here renders our own
   `cards.poster` template (`coral.score`), not the stock `card.score` — Zangetsu's relation cards
   carry no score badge, so it is hidden. */
[data-slot="detail"][data-variant="phone"] [data-slot="detail.relations"] { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px 12px; margin-top: 18px; }
[data-slot="detail.relations"] [data-part="coral.score"] { display: none !important; }

/* Overview laid out like Zangetsu's Details tab: plain 96 px label column, synopsis last. No `fact`
   hook covers the section wrapper, so it is still found structurally. */
[data-slot="detail"][data-variant="phone"] div:has(> section > dl > [data-part="fact"]) { display: flex; flex-direction: column; gap: 14px; margin-top: 20px; }
[data-slot="detail"][data-variant="phone"] div:has(> section > dl > [data-part="fact"]) > section { margin-top: 0; }
[data-slot="detail"][data-variant="phone"] div:has(> section > dl > [data-part="fact"]) > section:has(> [data-part="detail.synopsis"]) { order: 9; margin-top: 6px; }
[data-slot="detail"][data-variant="phone"] div:has(> section > dl > [data-part="fact"]) > section > h2 { margin-bottom: 10px; font-size: 13px; line-height: 1.3; font-weight: 500; color: #6e6e78; }
[data-slot="detail"][data-variant="phone"] div:has(> section > dl > [data-part="fact"]) > section:has(> dl) > h2 { display: none; }
[data-slot="detail"][data-variant="phone"] dl:has(> [data-part="fact"]) { display: block; }
[data-slot="detail"][data-variant="phone"] dl > [data-part="fact"] { display: grid; grid-template-columns: 96px minmax(0, 1fr); margin-bottom: 10px; padding: 0; border-radius: 0; background: none; }
[data-slot="detail"][data-variant="phone"] dl > [data-part="fact"] > [data-part="fact.label"] { font-size: 13px; line-height: 1.3; font-weight: 500; letter-spacing: 0; text-transform: none; color: #6e6e78; }
[data-slot="detail"][data-variant="phone"] dl > [data-part="fact"] > [data-part="fact.value"] { margin-top: 0; font-size: 13px; line-height: 1.3; font-weight: 600; color: #fff; }
[data-slot="detail"][data-variant="phone"] section > p[data-part="detail.synopsis"] { font-size: 15px; line-height: 1.35; color: #a7a7b2; }

/* Cast: 3-column grid of square photos (real `person`/`person.photo`/`person.name`/`person.role`
   hooks now). The character's narrative role (MAIN/SUPPORTING) is hidden; the nested voice-actor
   block's own photo is hidden too, leaving its name as the caption — Zangetsu's "first Japanese VA". */
[data-slot="detail.characters"] > div { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px 12px; }
[data-slot="detail.characters"] [data-part="person"] { flex-direction: column; align-items: center; border: 0; border-radius: 0; background: none; text-align: center; padding: 0; min-width: 0; }
[data-slot="detail.characters"] [data-part="person.photo"] { width: 100%; aspect-ratio: 1; border-radius: 12px; object-fit: cover; }
[data-slot="detail.characters"] [data-part="person"] > div { width: 100%; min-width: 0; padding: 6px 0 0; }
[data-slot="detail.characters"] [data-part="person.name"] { width: 100%; font-size: 13px; line-height: 1.3; }
[data-slot="detail.characters"] [data-part="person.role"] { display: none; }
[data-slot="detail.characters"] [data-part="person"] img:not([data-part="person.photo"]) { display: none; }
[data-slot="detail.characters"] [data-part="person"] > div > div:last-child:not([data-part="person.role"]) { width: 100%; min-width: 0; margin-top: 2px; font-size: 11px; color: #a7a7b2; }
[data-slot="detail.characters"] [data-part="person"] > div > div:last-child:not([data-part="person.role"]) div { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* No dock on the series page (`detail.nav: "hidden"` in design.json suppresses it; no CSS needed). */

/* The floating dock: frosted capsule, 7 % white hairline, colour-and-glyph active state only. */
[data-slot="nav.bottom"] { border-color: rgba(255, 255, 255, 0.07) !important; }
